export const makeT = (lang) => (key, vars) => {
  const text = messages[lang]?.[key] ?? messages.en[key] ?? key;
  return vars ? text.replace(/\{(\w+)\}/g, (_, name) => vars[name] ?? '') : text;
};

// Per-page-group text files (src/admin/i18n-pages/*.js) are merged over the base messages.
import shell from './i18n-pages/shell.js';
import catalog from './i18n-pages/catalog.js';
import importPages from './i18n-pages/import.js';
import translate from './i18n-pages/translate.js';
import community from './i18n-pages/community.js';
import system from './i18n-pages/system.js';

import review1 from './i18n-pages/review-1.js';
import review2 from './i18n-pages/review-2.js';
import review3 from './i18n-pages/review-3.js';
import review4 from './i18n-pages/review-4.js';
import review5 from './i18n-pages/review-5.js';
import review6 from './i18n-pages/review-6.js';
import review7 from './i18n-pages/review-7.js';

for (const extra of [shell, catalog, importPages, translate, community, system, review1, review2, review3, review4, review5, review6, review7]) {
  Object.assign(messages.en, extra.en);
  Object.assign(messages.fa, extra.fa);
}
